<script setup>
import {onMounted,onUnmounted,ref} from 'vue';import {get} from '../api/client';import DataTable from '../components/DataTable.vue'
const jobs=ref([]),selected=ref(null),dataDir=ref('data'),source=ref('sina'),top=ref(30),message=ref(''),timer=ref();const labels={collect:'拉取收盘增量',predict:'执行预测',verify:'执行正式验证',intraday:'获取盘中观察',pipeline:'完整每日流水线'};const taskHelp={collect:{time:'交易日15:10后',text:'获取当日收盘快照，生成每日增量并同步数据库。收盘前执行会被拒绝，不会写入正式增量。'},predict:{time:'行情同步后',text:'使用当前最新日线计算因子和候选名单。相同基准日重复执行会更新同一批次，不重复创建行情。'},verify:{time:'下一交易日收盘行情入库后',text:'用实际次日收盘价验证已有预测。行情不足时只显示等待验证；重复执行会更新同一验证结果。'},intraday:{time:'交易时段内按需执行',text:'获取一次实时快照并新增盘中观察记录，不修改历史日线、预测候选或正式验证。'},pipeline:{time:'交易日15:10后推荐',text:'依次执行收盘增量、同步日线、验证上一期、生成下一期预测，是日常收盘后的标准流程。'}};
async function refresh(){jobs.value=await get('/tasks?limit=30');if(selected.value)selected.value=await get(`/tasks/${selected.value.id}`);const active=jobs.value.some(x=>['pending','running'].includes(x.status));if(active&&!timer.value)timer.value=setInterval(refresh,2000);if(!active&&timer.value){clearInterval(timer.value);timer.value=null}}
async function submit(job_type){message.value='';try{const r=await fetch('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_type,data_dir:dataDir.value,source:source.value,top:Number(top.value)})});const body=await r.json();if(!r.ok)throw new Error(body.detail||'提交失败');message.value=`任务 #${body.id} 已提交`;await refresh()}catch(e){message.value=e.message}}
async function show(row){if(selected.value?.id===row.id){selected.value=null;return}selected.value=await get(`/tasks/${row.id}`)}onMounted(refresh);onUnmounted(()=>timer.value&&clearInterval(timer.value));const columns=[{label:'任务ID',key:'id',format:v=>`#${v}`,action:show},{label:'任务',key:'job_type',format:v=>labels[v]||v},{label:'状态',key:'status'},{label:'进度',key:'progress',format:v=>`${v}%`},{label:'创建时间',key:'created_at'},{label:'结束时间',key:'finished_at'}]
</script><template><div class="card task-panel"><h2>新建任务</h2><p class="hint">任务在后台执行，同一时间只允许一个任务运行。</p><div class="safety-note"><b>数据安全：</b>日线按“股票+交易日”唯一保存；重复同步不会生成重复行情。正式增量只能在交易日收盘后生成。</div><div class="task-config"><label>数据目录<input v-model="dataDir"></label><label>行情来源<select v-model="source"><option value="sina">新浪</option><option value="eastmoney">东方财富</option><option value="auto">自动切换</option></select></label><label>候选数量<input v-model.number="top" type="number" min="1" max="500"></label></div><div class="task-actions"><article v-for="(label,key) in labels"><div><h3>{{label}}</h3><span>{{taskHelp[key].time}}</span></div><p>{{taskHelp[key].text}}</p><button @click="submit(key)">执行{{label}}</button></article></div><p v-if="message" class="notice">{{message}}</p></div><div class="section"><div class="section-heading"><h2>最近任务</h2><span>再次点击同一任务ID可收起</span></div><DataTable :columns="columns" :rows="jobs"/></div><div v-if="selected" class="section card"><div class="detail-heading"><h2>任务 #{{selected.id}} · {{labels[selected.job_type]}}</h2><button @click="selected=null">收起详情</button></div><div class="progress"><i :style="{width:`${selected.progress}%`}"></i></div><p>状态：<b>{{selected.status}}</b>　进度：{{selected.progress}}%</p><p v-if="selected.error_message" class="negative">{{selected.error_message}}</p><pre>{{selected.log_text||'等待日志…'}}</pre></div></template>
